mapper.sql:
WITH valid_pp AS ( SELECT pp.* FROM lx_purchase_plan pp WHERE pp.status NOT IN (-3, 122, 124) AND pp.create_time IS NOT NULL AND pp.create_time <= #{query.asOf}
AND pp.plan_sn = #{planSn}
AND EXISTS ( SELECT 1 FROM lx_pp_po_sku_ass ass WHERE ass.plan_sn = pp.plan_sn AND ass.order_sn = #{orderSn} )
AND pp.create_time >= #{query.startDate}
AND pp.create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
), /* PO×SKU 事实：直接读 PO×SKU 粒度宽表 po_sku_facts_snapshot（同步任务预聚合）， 已反规范化 PO 头 + SKU 收货/入库单号串与有无标志。line_qty 为 SKU 合并后的采购 数量，completion_inbound_sn / completion_at 为 SKU 级达标；receipt_sns / inbound_sns 为逗号分隔，供列表关键字 LIKE 与节点判定。达标粒度按宽表口径下沉到 SKU， 不改 PP×SKU 口径。 */ po_sku_facts AS ( SELECT pdf.order_sn, pdf.sku, pdf.product_name, pdf.line_qty, pdf.completion_inbound_sn, pdf.completion_at, pdf.purchase_qty_raw, pdf.entry_qty, pdf.return_qty, pdf.exchange_qty, pdf.receipt_sns, pdf.inbound_sns, pdf.has_receipt, pdf.has_inbound, pdf.order_id, pdf.status, pdf.status_text, pdf.settlement_method, pdf.alibaba_order_sn, pdf.supplier, pdf.warehouse, pdf.buyer, pdf.created_at, pdf.approval_at, pdf.sent_at FROM po_sku_facts_snapshot pdf WHERE pdf.created_at <= #{query.asOf} ), /* 列表（主记录）与详情共用的 PO 整单事实（订单级）：从 enriched PO×SKU 宽表 GROUP BY order_sn 还原。仅用于订单级过滤（keyword / buyer / supplier / warehouse / deliveryStatus / risk）与订单详情页的 PO 整单口径字段；PP 级 delivery / current_node 不由此聚合（见 pp_sku_delivery / pp_facts，一律按 SKU 口径）。 */ po_facts_lite AS ( SELECT pofr.*,
FROM ( SELECT MAX(psf.order_id) AS order_id, psf.order_sn, MAX(psf.status) AS status, MAX(psf.status_text) AS status_text, MAX(psf.supplier) AS supplier, MAX(psf.warehouse) AS warehouse, MAX(psf.buyer) AS buyer, MAX(psf.settlement_method) AS settlement_method, MAX(psf.alibaba_order_sn) AS alibaba_order_sn, MAX(psf.created_at) AS created_at, MAX(psf.approval_at) AS approval_at, MAX(psf.sent_at) AS sent_at, SUM(psf.line_qty) AS purchase_qty, GROUP_CONCAT(DISTINCT psf.sku ORDER BY psf.sku SEPARATOR '、') AS skus, GROUP_CONCAT(DISTINCT psf.product_name ORDER BY psf.product_name SEPARATOR '、') AS product_names, GROUP_CONCAT(DISTINCT NULLIF(TRIM(psf.receipt_sns), '') ORDER BY NULLIF(TRIM(psf.receipt_sns), '') SEPARATOR ',') AS receipt_sns, GROUP_CONCAT(DISTINCT NULLIF(TRIM(psf.inbound_sns), '') ORDER BY NULLIF(TRIM(psf.inbound_sns), '') SEPARATOR ',') AS inbound_sns, MAX(psf.has_receipt) AS has_receipt, MAX(psf.has_inbound) AS has_inbound, CASE WHEN COUNT(CASE WHEN psf.line_qty > 0 THEN 1 END) > 0 AND COUNT(CASE WHEN psf.line_qty > 0 THEN 1 END) = COUNT(CASE WHEN psf.line_qty > 0 AND psf.completion_at IS NOT NULL THEN 1 END) THEN MAX(psf.completion_at) END AS completion_at, CASE WHEN COUNT(CASE WHEN psf.line_qty > 0 THEN 1 END) > 0 AND COUNT(CASE WHEN psf.line_qty > 0 THEN 1 END) = COUNT(CASE WHEN psf.line_qty > 0 AND psf.completion_at IS NOT NULL THEN 1 END) THEN SUBSTRING_INDEX( GROUP_CONCAT(psf.completion_inbound_sn ORDER BY psf.completion_at DESC, psf.sku SEPARATOR '||'), '||', 1 ) END AS completion_inbound_sn FROM po_sku_facts psf GROUP BY psf.order_sn ) pofr ), /* PP-PO-SKU 关系唯一由 lx_pp_po_sku_ass 提供（plan_sn×order_sn×sku，带 idx_pp_po_sku 索引）。下游所有 PP×PO 关联一律通过 relation_skus 的 (order_sn, sku) 连接宽表/原始表确定，不再对 PO item 的 JSON 关联字段做 逐行判定——JSON 函数无法走索引，是明细/列表查询的主要开销。该表和原始 PO item 都没有分摊数量，因此这里只用于确定关联关系，不推算任何 PP 分摊数量。 */ relation_skus AS ( SELECT DISTINCT ass.plan_sn, ass.order_sn, NULLIF(TRIM(ass.sku), '') AS sku FROM lx_pp_po_sku_ass ass INNER JOIN valid_pp pp ON pp.plan_sn = ass.plan_sn INNER JOIN po_facts_lite pfl ON pfl.order_sn = ass.order_sn WHERE ass.plan_sn IS NOT NULL AND ass.plan_sn <> '' AND ass.order_sn IS NOT NULL AND ass.order_sn <> '' ), relation_orders AS ( SELECT DISTINCT rs.plan_sn, rs.order_sn FROM relation_skus rs ), /* PP 稳定事实：直接读 PP 粒度宽表 pp_delivery_facts（同步任务预聚合）。数量、 达标行数、关联 PO / 采购员 / 供应商 / 仓库 / 单号串、SKU 达标与最早节点均为 SKU 口径；asOf 依赖的交付派生列仍由 pp_sku_delivery / plan_facts 现算。 */ pp_facts AS ( SELECT pdf.plan_sn, pdf.product_name, pdf.sku, pdf.status_text, pdf.approval_status, pdf.pp_supplier, pdf.created_at, pdf.approval_at, pdf.plan_qty, pdf.purchase_qty, pdf.inbound_qty AS po_inbound_qty, pdf.returned_qty, pdf.exchange_qty, pdf.related_sku_line_count, pdf.completed_sku_line_count, pdf.related_order_count, pdf.order_sns, pdf.buyers, pdf.suppliers, pdf.warehouses, pdf.related_skus, pdf.last_po_created_at, pdf.first_sent_at, pdf.first_completion_at, pdf.completed_status_order_count, pdf.earliest_po_node_rank FROM pp_delivery_facts pdf WHERE pdf.created_at <= #{query.asOf} ), /* PP×SKU 交付派生（asOf 依赖，现算）：按 relation_skus 关联的 SKU 行逐行判定 delivery_hours / delivery_status，再聚合为 PP 级交付状态，不按 PO 整单。 */ pp_sku_delivery AS ( SELECT rs.plan_sn, MAX(CASE WHEN psf.sent_at IS NULL THEN NULL ELSE TIMESTAMPDIFF(HOUR, psf.sent_at, COALESCE(psf.completion_at, #{query.asOf})) END) AS max_delivery_hours, SUBSTRING_INDEX( GROUP_CONCAT( CASE WHEN psf.line_qty > 0 AND psf.completion_at IS NOT NULL THEN CASE WHEN psf.completion_at <= DATE_ADD(psf.sent_at, INTERVAL 360 HOUR) THEN 'COMPLETED_WITHIN_SLA' ELSE 'COMPLETED_OVER_SLA' END END ORDER BY psf.completion_at, psf.sku SEPARATOR '||' ), '||', 1 ) AS first_completion_delivery_status, SUM(CASE WHEN psf.line_qty > 0 AND psf.sent_at IS NULL THEN 1 ELSE 0 END) AS pending_sku_line_count, SUM(CASE WHEN psf.line_qty > 0 AND psf.completion_at IS NULL AND #{query.asOf} >= DATE_ADD(psf.sent_at, INTERVAL 360 HOUR) THEN 1 ELSE 0 END) AS transit_overdue_sku_line_count, SUM(CASE WHEN psf.line_qty > 0 AND psf.completion_at IS NOT NULL AND psf.completion_at > DATE_ADD(psf.sent_at, INTERVAL 360 HOUR) THEN 1 ELSE 0 END) AS completed_over_sla_sku_line_count FROM relation_skus rs INNER JOIN po_sku_facts psf ON psf.order_sn = rs.order_sn AND psf.sku <=> rs.sku GROUP BY rs.plan_sn ), /* 原始数据不包含 PP 分摊数量，所有分摊字段固定为不可用。 */ plan_allocation AS ( SELECT rel.plan_sn, 0 AS allocation_available, CAST(NULL AS SIGNED) AS allocated_qty, CAST(NULL AS SIGNED) AS inbound_qty FROM relation_orders rel GROUP BY rel.plan_sn ), plan_rollup AS ( SELECT pf.plan_sn, pf.product_name, pf.sku, pf.status_text, pf.approval_status, pf.pp_supplier, pf.created_at, pf.approval_at, pf.plan_qty, COALESCE(pf.purchase_qty, 0) AS purchase_qty, COALESCE(pf.po_inbound_qty, 0) AS po_inbound_qty, COALESCE(pf.returned_qty, 0) AS returned_qty, COALESCE(pf.exchange_qty, 0) AS exchange_qty, COALESCE(pf.related_order_count, 0) AS related_order_count, pf.order_sns, pf.buyers, pf.suppliers, pf.warehouses, pf.related_skus, pf.last_po_created_at, pf.first_sent_at, TIMESTAMPDIFF(HOUR, pf.created_at, COALESCE(pf.last_po_created_at, #{query.asOf})) AS order_lead_hours, pf.earliest_po_node_rank, psd.max_delivery_hours, pf.first_completion_at, psd.first_completion_delivery_status, COALESCE(pf.related_sku_line_count, 0) AS related_sku_line_count, COALESCE(pf.completed_sku_line_count, 0) AS completed_sku_line_count, COALESCE(pf.completed_status_order_count, 0) AS completed_status_order_count, COALESCE(psd.pending_sku_line_count, 0) AS pending_sku_line_count, COALESCE(psd.transit_overdue_sku_line_count, 0) AS transit_overdue_sku_line_count, COALESCE(psd.completed_over_sla_sku_line_count, 0) AS completed_over_sla_sku_line_count, pa.allocation_available AS allocation_evaluable, pa.allocated_qty, pa.inbound_qty AS allocated_inbound_qty FROM pp_facts pf LEFT JOIN pp_sku_delivery psd ON psd.plan_sn = pf.plan_sn LEFT JOIN plan_allocation pa ON pa.plan_sn = pf.plan_sn ), plan_facts AS ( SELECT pr.*, CASE WHEN pr.last_po_created_at IS NOT NULL AND pr.last_po_created_at < DATE_ADD(pr.created_at, INTERVAL 24 HOUR) THEN 'TIMELY' WHEN pr.last_po_created_at IS NULL AND #{query.asOf} < DATE_ADD(pr.created_at, INTERVAL 24 HOUR) THEN 'ORDERING' ELSE 'OVERDUE' END AS order_timeliness, CASE WHEN pr.last_po_created_at IS NOT NULL THEN 1 ELSE 0 END AS order_coverage_confirmed, CASE WHEN pr.status_text = '已完成' AND pr.related_order_count = 0 THEN 'COMPLETED' WHEN pr.related_order_count > 0 AND pr.related_sku_line_count > 0 AND pr.completed_sku_line_count = pr.related_sku_line_count THEN 'COMPLETED' WHEN pr.related_order_count > 0 AND pr.completed_status_order_count = pr.related_order_count THEN 'COMPLETED' WHEN pr.status_text = '待审批' THEN 'PP_CREATE' WHEN pr.status_text = '待采购' THEN 'PP_APPROVAL' WHEN pr.related_order_count = 0 THEN 'PP_APPROVAL' WHEN pr.earliest_po_node_rank = 3 THEN 'PO_CREATE' WHEN pr.earliest_po_node_rank = 4 THEN 'PO_APPROVAL' WHEN pr.earliest_po_node_rank = 5 THEN 'SUPPLIER_SENT' WHEN pr.earliest_po_node_rank = 6 THEN 'FINANCE_PAYMENT' WHEN pr.earliest_po_node_rank = 7 THEN 'CR_RECEIPT' WHEN pr.earliest_po_node_rank = 8 THEN 'IB_CREATE' ELSE CAST(NULL AS CHAR) END AS current_node, CASE WHEN pr.related_order_count = 0 THEN 'PENDING' WHEN pr.completed_sku_line_count > 0 AND pr.first_completion_delivery_status = 'COMPLETED_OVER_SLA' THEN 'COMPLETED_OVER_SLA' WHEN pr.completed_sku_line_count > 0 THEN 'COMPLETED_WITHIN_SLA' WHEN pr.completed_over_sla_sku_line_count > 0 OR pr.transit_overdue_sku_line_count > 0 THEN 'IN_TRANSIT_OVERDUE' WHEN pr.pending_sku_line_count > 0 THEN 'PENDING' ELSE 'IN_TRANSIT' END AS delivery_status, CASE WHEN pr.plan_qty > 0 AND pr.allocation_evaluable = 1 THEN 1 ELSE 0 END AS allocation_available, pr.po_inbound_qty AS inbound_qty, CASE WHEN pr.purchase_qty > 0 THEN LEAST( CAST(100 AS DECIMAL(18, 4)), CAST(pr.po_inbound_qty * 100.0 / pr.purchase_qty AS DECIMAL(18, 4)) ) ELSE NULL END AS achievement_rate FROM plan_rollup pr )

, filtered_relation_orders AS ( SELECT DISTINCT rel.plan_sn, rel.order_sn FROM relation_orders rel INNER JOIN valid_pp pp ON pp.plan_sn = rel.plan_sn INNER JOIN po_facts_lite pof ON pof.order_sn = rel.order_sn WHERE 1 = 1
AND ( pp.plan_sn LIKE CONCAT('%', #{query.keyword}, '%') OR pp.sku LIKE CONCAT('%', #{query.keyword}, '%') OR pp.product_name LIKE CONCAT('%', #{query.keyword}, '%') OR pp.supplier_name LIKE CONCAT('%', #{query.keyword}, '%') OR pof.order_sn LIKE CONCAT('%', #{query.keyword}, '%') OR pof.skus LIKE CONCAT('%', #{query.keyword}, '%') OR pof.product_names LIKE CONCAT('%', #{query.keyword}, '%') OR pof.supplier LIKE CONCAT('%', #{query.keyword}, '%') OR pof.receipt_sns LIKE CONCAT('%', #{query.keyword}, '%') OR pof.inbound_sns LIKE CONCAT('%', #{query.keyword}, '%') )
AND pof.buyer = #{query.buyer}
AND pof.supplier = #{query.supplier}
AND pof.warehouse = #{query.warehouse}
AND pof.delivery_status = #{query.deliveryStatus}
)

/* valid_po：详情专用「有效 PO」。列表不再 JOIN lx_purchase_order（PO 头读宽表）， 详情仍读原始表保持实时口径；planSn/orderSn 收窄在入口落地。 */ , valid_po AS ( SELECT po.* FROM lx_purchase_order po WHERE po.status NOT IN (-1, 124) AND po.create_time IS NOT NULL AND po.create_time <= #{query.asOf}
AND EXISTS ( SELECT 1 FROM lx_pp_po_sku_ass ass WHERE ass.order_sn = po.order_sn AND ass.plan_sn = #{planSn} )
AND po.order_sn = #{orderSn}
), po_sent_log_ranked AS ( SELECT po.order_sn, bl.id AS sent_log_id, bl.ol_time AS sent_at, bl.realname AS sent_operator, ROW_NUMBER() OVER ( PARTITION BY po.order_sn ORDER BY bl.ol_time ASC, bl.id ASC ) AS rn FROM valid_po po INNER JOIN lx_business_log bl ON bl.business_id = CONCAT('1_', po.order_sn) WHERE bl.ol_type_text = '下单' AND bl.ol_time IS NOT NULL AND bl.ol_time <= #{query.asOf} ), po_sent_log AS ( SELECT order_sn, sent_log_id, sent_at, sent_operator FROM po_sent_log_ranked WHERE rn = 1 ), /* CR 收货事实（PO 级，原始表）：按宽表口径改用 (business_order_sn, sku) 关联， 供详情页与时间线取 '||' 分隔收货单号 / 精确单量。 */ receipt_facts AS ( SELECT ro.id AS receipt_id, ro.order_sn AS receipt_sn, ro.business_order_sn AS order_sn, ro.create_time AS created_at, ro.create_realname AS operator_name, SUM(GREATEST(COALESCE(roi.product_receive_num, 0), 0)) AS receipt_qty FROM lx_receipt_order ro INNER JOIN lx_receipt_order_item roi ON roi.order_sn = ro.order_sn WHERE ro.create_time IS NOT NULL AND ro.create_time <= #{query.asOf} GROUP BY ro.id, ro.order_sn, ro.business_order_sn, ro.create_time, ro.create_realname ), receipt_summary AS ( SELECT rf.order_sn, COUNT(DISTINCT rf.receipt_id) AS receipt_count, GROUP_CONCAT(DISTINCT rf.receipt_sn ORDER BY rf.created_at, rf.receipt_id SEPARATOR '||') AS receipt_sns, MIN(rf.created_at) AS first_receipt_at FROM receipt_facts rf GROUP BY rf.order_sn ), receipt_sku_facts AS ( SELECT ro.id AS receipt_id, ro.order_sn AS receipt_sn, ro.business_order_sn AS order_sn, NULLIF(TRIM(roi.sku), '') AS sku, ro.create_time AS created_at, ro.create_realname AS operator_name, SUM(GREATEST(COALESCE(roi.product_receive_num, 0), 0)) AS receipt_qty FROM lx_receipt_order ro INNER JOIN lx_receipt_order_item roi ON roi.order_sn = ro.order_sn WHERE ro.create_time IS NOT NULL AND ro.create_time <= #{query.asOf} GROUP BY ro.id, ro.order_sn, ro.business_order_sn, NULLIF(TRIM(roi.sku), ''), ro.create_time, ro.create_realname ), /* PO×SKU 维度 CR 收货汇总：PO 详情按单个 SKU 限定时的 CR 单号/单量。 */ order_sku_receipt_summary AS ( SELECT rsf.order_sn, rsf.sku, COUNT(DISTINCT rsf.receipt_id) AS receipt_count, GROUP_CONCAT(DISTINCT rsf.receipt_sn ORDER BY rsf.created_at, rsf.receipt_id SEPARATOR '||') AS receipt_sns, SUM(rsf.receipt_qty) AS receipt_qty FROM receipt_sku_facts rsf GROUP BY rsf.order_sn, rsf.sku ), /* PP×PO 维度 CR 收货汇总：PO 详情按 PP×PO 关联 SKU 限定时的 CR 单号/单量。 */ pp_po_receipt_summary AS ( SELECT rs.plan_sn, rs.order_sn, COUNT(DISTINCT rsf.receipt_id) AS receipt_count, GROUP_CONCAT(DISTINCT rsf.receipt_sn ORDER BY rsf.created_at, rsf.receipt_id SEPARATOR '||') AS receipt_sns FROM relation_skus rs INNER JOIN receipt_sku_facts rsf ON rsf.order_sn = rs.order_sn AND rsf.sku <=> rs.sku GROUP BY rs.plan_sn, rs.order_sn ), /* 有效 IB 明细（原始表）：白名单口径（status IN (20,40) + product_total≥0）， 关联宽表取 (order_sn, sku)。这里仅用于详情页单号列表与逐单时间线。 */ valid_ib_items AS ( SELECT ib.id AS inbound_id, ib.order_sn AS inbound_sn, pdf.order_sn, ibi.purchase_item_id AS purchase_item_id, NULLIF(TRIM(pdf.sku), '') AS sku, ib.create_time AS created_at, COALESCE(ib.create_realname, ib.opt_realname) AS operator_name, ibi.product_total AS inbound_qty FROM lx_inbound_order ib INNER JOIN lx_inbound_order_item ibi ON ibi.order_sn = ib.order_sn INNER JOIN po_item_delivery_facts pdf ON pdf.po_item_id = ibi.purchase_item_id AND pdf.order_sn = ib.purchase_order_sn WHERE ), ib_per_document AS ( SELECT vii.inbound_id, vii.inbound_sn, vii.order_sn, vii.created_at, MAX(vii.operator_name) AS operator_name, SUM(vii.inbound_qty) AS inbound_qty FROM valid_ib_items vii GROUP BY vii.inbound_id, vii.inbound_sn, vii.order_sn, vii.created_at ), /* PO 整单有效 IB 汇总（原始表）：单量、'||' 分隔单号、累计有效入库。 */ po_ib_sn_summary AS ( SELECT ibd.order_sn, COUNT(*) AS inbound_count, GROUP_CONCAT(ibd.inbound_sn ORDER BY ibd.created_at, ibd.inbound_id SEPARATOR '||') AS inbound_sns, SUM(ibd.inbound_qty) AS valid_inbound_qty FROM ib_per_document ibd GROUP BY ibd.order_sn ), /* PO×SKU 有效 IB 汇总：供 PO 详情按单个 SKU 限定时的单量/单号列表。 */ order_sku_ib_summary AS ( SELECT per_doc.order_sn, per_doc.sku, COUNT(*) AS inbound_count, GROUP_CONCAT(per_doc.inbound_sn ORDER BY per_doc.created_at, per_doc.inbound_id SEPARATOR '||') AS inbound_sns, SUM(per_doc.inbound_qty) AS valid_inbound_qty FROM ( SELECT vii.inbound_id, vii.inbound_sn, vii.order_sn, vii.sku, vii.created_at, SUM(vii.inbound_qty) AS inbound_qty FROM valid_ib_items vii GROUP BY vii.inbound_id, vii.inbound_sn, vii.order_sn, vii.sku, vii.created_at ) per_doc GROUP BY per_doc.order_sn, per_doc.sku ), /* PP×PO 有效 IB 汇总：供 PO 详情按 PP×PO 关联 SKU 限定时的单号列表。 */ pp_po_ib_summary AS ( SELECT rs.plan_sn, rs.order_sn, COUNT(DISTINCT vii.inbound_id) AS inbound_count, GROUP_CONCAT(DISTINCT vii.inbound_sn ORDER BY vii.created_at, vii.inbound_id SEPARATOR '||') AS inbound_sns FROM relation_skus rs INNER JOIN valid_ib_items vii ON vii.order_sn = rs.order_sn AND vii.sku <=> rs.sku GROUP BY rs.plan_sn, rs.order_sn ), /* PP×PO 维度数量：PP 详情「关联 PO」的采购数量（SKU 合并口径）。 */ pp_po_item_totals AS ( SELECT rs.plan_sn, rs.order_sn, SUM(psf.line_qty) AS purchase_qty FROM relation_skus rs INNER JOIN po_sku_facts psf ON psf.order_sn = rs.order_sn AND psf.sku <=> rs.sku GROUP BY rs.plan_sn, rs.order_sn ), /* PP×PO 维度累计有效入库（白名单口径）。 */ pp_po_inbound_totals AS ( SELECT rs.plan_sn, rs.order_sn, SUM(vii.inbound_qty) AS valid_inbound_qty FROM relation_skus rs INNER JOIN valid_ib_items vii ON vii.order_sn = rs.order_sn AND vii.sku <=> rs.sku GROUP BY rs.plan_sn, rs.order_sn ), /* PP×PO 维度达标：PP 详情「关联 PO」的达标IB。与 po_completion（PO 整单）不同，这里 按单个 PP 在某 PO 关联的 SKU 判定——共享 PO 时只受本 PP 关联 SKU 影响，不被其他 PP 的 SKU 阻塞；判定口径与 pp_sku_completion 一致，只是细到 PO。 */ pp_po_sku_completion AS ( SELECT rs.plan_sn, rs.order_sn, CASE WHEN COUNT(CASE WHEN psf.line_qty > 0 THEN 1 END) > 0 AND COUNT(CASE WHEN psf.line_qty > 0 THEN 1 END) = COUNT(CASE WHEN psf.line_qty > 0 AND psf.completion_at IS NOT NULL THEN 1 END) THEN MAX(psf.completion_at) END AS completion_at, CASE WHEN COUNT(CASE WHEN psf.line_qty > 0 THEN 1 END) > 0 AND COUNT(CASE WHEN psf.line_qty > 0 THEN 1 END) = COUNT(CASE WHEN psf.line_qty > 0 AND psf.completion_at IS NOT NULL THEN 1 END) THEN SUBSTRING_INDEX( GROUP_CONCAT(psf.completion_inbound_sn ORDER BY psf.completion_at DESC, psf.sku SEPARATOR '||'), '||', 1 ) END AS completion_inbound_sn FROM relation_skus rs INNER JOIN po_sku_facts psf ON psf.order_sn = rs.order_sn AND psf.sku <=> rs.sku GROUP BY rs.plan_sn, rs.order_sn ), /* 原始数据不包含 PP 分摊数量，所有分摊字段固定为不可用。 */ plan_order_allocation AS ( SELECT rel.plan_sn, rel.order_sn, 0 AS allocation_available, CAST(NULL AS SIGNED) AS allocated_qty, CAST(NULL AS SIGNED) AS inbound_qty FROM relation_orders rel ), order_allocation AS ( SELECT rel.order_sn, COUNT(DISTINCT rel.plan_sn) AS related_plan_count, 0 AS allocation_available, CAST(NULL AS SIGNED) AS allocated_qty FROM relation_orders rel GROUP BY rel.order_sn ), /* PO 整单达标：全部正数量 SKU 均达标才视为完成，直接读列表共用的 po_facts_lite （已按 order_sn 还原 PO 整单达标），供详情/时间线逐单累计标注达标节点。 */ po_completion AS ( SELECT pfl.order_sn, pfl.completion_inbound_sn, pfl.completion_at FROM po_facts_lite pfl ), /* 详情 PO 事实（实时口径）：收货/入库单量、'||' 分隔单号、有效入库累计仍读原始表 receipt_summary / po_ib_sn_summary，保证详情页单号可解析、单量精确、节点实时。 has_receipt / has_inbound 由精确单量推导，与列表宽表口径的布尔等价，供共用派生列。 */ po_facts_raw AS ( SELECT po.id AS order_id, po.order_sn, pfl.skus, pfl.product_names, po.status, po.status_text, po.supplier_name AS supplier, po.ware_house_name AS warehouse, po.opt_realname AS buyer, po.settlement_method, CASE WHEN po.settlement_method = 7 THEN 'SPOT' WHEN po.settlement_method = 8 THEN 'MONTHLY' ELSE 'OTHER' END AS settlement_type, CASE WHEN NULLIF(TRIM(po.alibaba_order_sn), '') IS NOT NULL THEN '1688' ELSE 'NORMAL' END AS source_type, po.create_time AS created_at, po.auditor_time AS approval_at, pfl.sent_at, COALESCE(pfl.purchase_qty, 0) AS purchase_qty, COALESCE(rs.receipt_sns, '') AS receipt_sns, COALESCE(rs.receipt_count, 0) AS receipt_count, CASE WHEN COALESCE(rs.receipt_count, 0) > 0 THEN 1 ELSE 0 END AS has_receipt, rs.first_receipt_at, COALESCE(pis.inbound_sns, '') AS inbound_sns, COALESCE(pis.inbound_count, 0) AS inbound_count, CASE WHEN COALESCE(pis.inbound_count, 0) > 0 THEN 1 ELSE 0 END AS has_inbound, COALESCE(pis.valid_inbound_qty, 0) AS valid_inbound_qty, pfl.completion_inbound_sn, pfl.completion_at FROM valid_po po LEFT JOIN po_facts_lite pfl ON pfl.order_sn = po.order_sn LEFT JOIN receipt_summary rs ON rs.order_sn = po.order_sn LEFT JOIN po_ib_sn_summary pis ON pis.order_sn = po.order_sn ), po_facts AS ( SELECT pofr.*,
FROM po_facts_raw pofr )

mapper.select:
, filtered_plans AS ( SELECT pf.* FROM plan_facts pf WHERE 1 = 1
), node_scoped_plans AS ( SELECT pf.* FROM plan_facts pf WHERE 1 = 1
), latest_sync AS ( SELECT ( SELECT t.end_time FROM lx_sync_task t WHERE t.task_type IN ('plan', 'order+plan') AND t.status = 'success' AND t.end_time IS NOT NULL ORDER BY t.end_time DESC, t.id DESC LIMIT 1 ) AS plan_completed_at, ( SELECT t.end_time FROM lx_sync_task t WHERE t.task_type IN ('order', 'order+plan') AND t.status = 'success' AND t.end_time IS NOT NULL ORDER BY t.end_time DESC, t.id DESC LIMIT 1 ) AS order_completed_at ), summary_counts AS ( SELECT (SELECT COUNT(*) FROM node_scoped_plans) AS total, (SELECT COALESCE(SUM(current_node = 'PP_CREATE'), 0) FROM filtered_plans) AS pp_create_count, (SELECT COALESCE(SUM(current_node = 'PP_APPROVAL'), 0) FROM filtered_plans) AS pp_approval_count, (SELECT COALESCE(SUM(current_node = 'PO_CREATE'), 0) FROM filtered_plans) AS po_create_count, (SELECT COALESCE(SUM(current_node = 'PO_APPROVAL'), 0) FROM filtered_plans) AS po_approval_count, (SELECT COALESCE(SUM(current_node = 'SUPPLIER_SENT'), 0) FROM filtered_plans) AS supplier_sent_count, (SELECT COALESCE(SUM(current_node = 'FINANCE_PAYMENT'), 0) FROM filtered_plans) AS finance_payment_count, (SELECT COALESCE(SUM(current_node = 'CR_RECEIPT'), 0) FROM filtered_plans) AS receipt_count, (SELECT COALESCE(SUM(current_node = 'IB_CREATE'), 0) FROM filtered_plans) AS inbound_create_count, (SELECT COALESCE(SUM(current_node = 'COMPLETED'), 0) FROM filtered_plans) AS completed_count, (SELECT COALESCE(SUM(order_timeliness = 'OVERDUE'), 0) FROM node_scoped_plans) AS order_overdue_count, ( SELECT COUNT(DISTINCT selected_pf.plan_sn) FROM node_scoped_plans selected_pf INNER JOIN filtered_relation_orders fro ON fro.plan_sn = selected_pf.plan_sn INNER JOIN po_facts_lite pof ON pof.order_sn = fro.order_sn WHERE pof.delivery_status IN ('IN_TRANSIT_OVERDUE', 'COMPLETED_OVER_SLA') ) AS delivery_overdue_count ) SELECT sc.*, CASE WHEN ls.plan_completed_at IS NOT NULL AND ls.order_completed_at IS NOT NULL THEN 'success' ELSE 'incomplete' END AS sync_status, CASE WHEN ls.plan_completed_at IS NOT NULL AND ls.order_completed_at IS NOT NULL THEN LEAST(ls.plan_completed_at, ls.order_completed_at) ELSE NULL END AS data_updated_at FROM summary_counts sc CROSS JOIN latest_sync ls


SELECT pf.*
FROM plan_facts pf
WHERE pf.plan_sn = #{planSn}

mapper.sql:
SELECT CONCAT('PP_APPROVAL_', pp.id) AS event_id, 'PP' AS source_type, pp.plan_sn AS source_sn, pp.approval_time AS event_time, 'PP 最终审批' AS title, CONCAT('PP ', pp.plan_sn, ' 审批通过') AS description, pp.approver AS operator_name, CAST(NULL AS SIGNED) AS quantity, CAST(NULL AS SIGNED) AS cumulative_quantity FROM
relation_skus relation_orders
rel INNER JOIN valid_pp pp ON pp.plan_sn = rel.plan_sn WHERE rel.order_sn = #{orderSn} AND rel.sku <=> #{sku} AND pp.approval_time IS NOT NULL AND pp.approval_time <= #{query.asOf} AND rel.plan_sn = #{planSn} UNION ALL SELECT CONCAT('PO_CREATE_', po.id), 'PO', po.order_sn, po.create_time, 'PO 创建', '', po.opt_realname, NULL, NULL FROM valid_po po WHERE po.order_sn = #{orderSn} UNION ALL SELECT CONCAT('PO_APPROVAL_', po.id), 'PO', po.order_sn, po.auditor_time, 'PO 审批', 'PO 审批通过', po.auditor_realname, NULL, NULL FROM valid_po po WHERE po.order_sn = #{orderSn} AND po.auditor_time IS NOT NULL UNION ALL SELECT CONCAT('PO_SENT_', psl.sent_log_id), 'PO', psl.order_sn, psl.sent_at, '下发供应商', CASE WHEN NULLIF(TRIM(pof.supplier), '') IS NULL THEN '' ELSE CONCAT('供应商：', pof.supplier) END, COALESCE(psl.sent_operator, pof.buyer), NULL, NULL FROM po_facts pof INNER JOIN po_sent_log psl ON psl.order_sn = pof.order_sn WHERE pof.order_sn = #{orderSn} AND psl.sent_at IS NOT NULL UNION ALL SELECT CONCAT('PAY_', rfo.id), 'PAYMENT', rfo.order_sn, COALESCE(CAST(rfo.real_pay_time AS DATETIME), rfo.apply_time), CASE WHEN rfo.real_pay_time IS NOT NULL THEN '付款' ELSE '请款' END, CASE WHEN rfo.real_pay_time IS NOT NULL THEN '付款完成' ELSE '请款已提交' END, COALESCE(rfo.pay_user, rfo.apply_user), NULL, NULL FROM lx_request_funds_order_item rfoi INNER JOIN lx_request_funds_order rfo ON rfo.order_sn = rfoi.order_sn WHERE rfoi.business_sn = #{orderSn} AND rfo.status NOT IN (3, 122, 124) AND COALESCE(CAST(rfo.real_pay_time AS DATETIME), rfo.apply_time) <= #{query.asOf} UNION ALL
SELECT CONCAT('CR_', rsf.receipt_id), 'CR', rsf.receipt_sn, rsf.created_at, 'CR 收货', '', rsf.operator_name, rsf.receipt_qty, NULL FROM receipt_sku_facts rsf WHERE rsf.order_sn = #{orderSn} AND rsf.sku <=> #{sku}
SELECT CONCAT('CR_', rsf.receipt_id), 'CR', rsf.receipt_sn, MAX(rsf.created_at), 'CR 收货', '', MAX(rsf.operator_name), SUM(rsf.receipt_qty), NULL FROM relation_skus rs INNER JOIN receipt_sku_facts rsf ON rsf.order_sn = rs.order_sn AND rsf.sku <=> rs.sku WHERE rs.plan_sn = #{planSn} AND rs.order_sn = #{orderSn} GROUP BY rsf.receipt_id, rsf.receipt_sn
SELECT CONCAT('CR_', rf.receipt_id), 'CR', rf.receipt_sn, rf.created_at, 'CR 收货', '', rf.operator_name, rf.receipt_qty, NULL FROM receipt_facts rf WHERE rf.order_sn = #{orderSn}
UNION ALL
SELECT CONCAT('IB_', g.inbound_id), 'IB', g.inbound_sn, g.created_at, '有效 IB 创建', CASE WHEN psf.completion_inbound_sn = g.inbound_sn AND psf.completion_at = g.created_at THEN '累计达到采购数量，采购流程完成' ELSE '' END, NULL, g.inbound_qty, SUM(g.inbound_qty) OVER ( ORDER BY g.created_at, g.inbound_id, g.inbound_sn ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) FROM ( SELECT vii.inbound_id, vii.inbound_sn, vii.created_at, SUM(vii.inbound_qty) AS inbound_qty FROM valid_ib_items vii WHERE vii.order_sn = #{orderSn} AND vii.sku <=> #{sku} GROUP BY vii.inbound_id, vii.inbound_sn, vii.created_at ) g LEFT JOIN po_sku_facts psf ON psf.order_sn = #{orderSn} AND psf.sku <=> #{sku}
SELECT CONCAT('IB_', g.inbound_id), 'IB', g.inbound_sn, g.created_at, '有效 IB 创建', CASE WHEN ppc.completion_inbound_sn = g.inbound_sn AND ppc.completion_at = g.created_at THEN '累计达到采购数量，采购流程完成' ELSE '' END, NULL, g.inbound_qty, SUM(g.inbound_qty) OVER ( ORDER BY g.created_at, g.inbound_id, g.inbound_sn ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) FROM ( SELECT vii.inbound_id, vii.inbound_sn, vii.created_at, SUM(vii.inbound_qty) AS inbound_qty FROM valid_ib_items vii INNER JOIN relation_skus rs ON rs.order_sn = vii.order_sn AND rs.sku <=> vii.sku WHERE rs.plan_sn = #{planSn} AND rs.order_sn = #{orderSn} GROUP BY vii.inbound_id, vii.inbound_sn, vii.created_at ) g LEFT JOIN pp_po_sku_completion ppc ON ppc.plan_sn = #{planSn} AND ppc.order_sn = #{orderSn}
SELECT CONCAT('IB_', g.inbound_id), 'IB', g.inbound_sn, g.created_at, '有效 IB 创建', CASE WHEN pc.completion_inbound_sn = g.inbound_sn AND pc.completion_at = g.created_at THEN '累计达到采购数量，采购流程完成' ELSE '' END, g.operator_name, g.inbound_qty, SUM(g.inbound_qty) OVER ( ORDER BY g.created_at, g.inbound_id, g.inbound_sn ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) FROM ( SELECT vii.inbound_id, vii.inbound_sn, vii.created_at, MAX(vii.operator_name) AS operator_name, SUM(vii.inbound_qty) AS inbound_qty FROM valid_ib_items vii WHERE vii.order_sn = #{orderSn} GROUP BY vii.inbound_id, vii.inbound_sn, vii.created_at ) g LEFT JOIN po_completion pc ON pc.order_sn = #{orderSn}
